#!/usr/bin/env python3
"""Unit tests for verilog_slice.py"""

import io
import unittest
from unittest import mock

import verilog_slice
from verilog_slice import SliceError, elaborated_names, parse_modules, slice_text

DESIGN = """\
// Generated by CIRCT firtool-1.0.0
module Leaf(
  input  [3:0] a,
  output [3:0] y
);
  assign y = ~a;
endmodule

// Generated by CIRCT firtool-1.0.0
module Inner(
  input        clock,
  input  [3:0] a,
  output [3:0] y
);
  wire [3:0] _leaf_y;
  Leaf leaf (
    .a (a),
    .y (_leaf_y)
  );
  reg [3:0] r;
  always @(posedge clock)
    r <= _leaf_y;
  assign y = r;
endmodule

// Generated by CIRCT firtool-1.0.0
module Outer(
  input        clock,
  input  [3:0] a,
  output [3:0] y
);
  wire [3:0] _inner_y;
  Inner inner (
    .clock (clock),
    .a     (a),
    .y     (_inner_y)
  );
  Leaf leaf (
    .a (_inner_y),
    .y (y)
  );
endmodule

// Generated by CIRCT firtool-1.0.0
module Top(
  input        clock,
  input  [3:0] a,
  output [3:0] y
);
  Outer outer (
    .clock (clock),
    .a     (a),
    .y     (y)
  );
endmodule
"""


def modules_of(text, path="design.sv"):
    modules = {}
    order = []
    for m in parse_modules(path, text):
        modules[m.name] = m
        order.append(m.name)
    return modules, order


def slice_of(text, target, kept):
    modules, order = modules_of(text)
    return slice_text(modules, order, target, set(kept))


class ParseTest(unittest.TestCase):
    def test_modules_in_order(self):
        _, order = modules_of(DESIGN)
        self.assertEqual(order, ["Leaf", "Inner", "Outer", "Top"])

    def test_children(self):
        modules, _ = modules_of(DESIGN)
        self.assertEqual(modules["Outer"].children(set(modules)), {"Inner", "Leaf"})
        self.assertEqual(modules["Leaf"].children(set(modules)), set())

    def test_comment_naming_a_module_is_no_instance(self):
        text = DESIGN.replace("assign y = ~a;", "assign y = ~a; // Top")
        modules, _ = modules_of(text)
        self.assertEqual(modules["Leaf"].children(set(modules)), set())

    def test_stub_is_the_header(self):
        modules, _ = modules_of(DESIGN)
        self.assertEqual(
            modules["Inner"].stub(),
            "module Inner(\n  input        clock,\n  input  [3:0] a,\n"
            "  output [3:0] y\n);\nendmodule\n",
        )

    def test_stub_keeps_parameters(self):
        text = "module P #(parameter W = 4) (input [W-1:0] a);\n  wire x;\nendmodule\n"
        modules, _ = modules_of(text)
        self.assertEqual(
            modules["P"].stub(),
            "module P #(parameter W = 4) (input [W-1:0] a);\nendmodule\n",
        )

    def test_attribute_belongs_to_module(self):
        text = "(* keep_hierarchy *)\nmodule A(input a);\nendmodule\n"
        modules, _ = modules_of(text)
        self.assertTrue(modules["A"].text.startswith("(* keep_hierarchy *)"))

    def test_escaped_name(self):
        text = "module \\1d_ram (input a);\nendmodule\nmodule B(input a);\n  \\1d_ram r (.a(a));\nendmodule\n"
        modules, _ = modules_of(text)
        self.assertEqual(modules["B"].children(set(modules)), {"1d_ram"})

    def test_conditional_inside_module_is_kept(self):
        text = 'module A(input a);\n`ifndef SYNTHESIS\n  initial $display("x");\n`endif\nendmodule\n'
        modules, _ = modules_of(text)
        self.assertIn("`ifndef SYNTHESIS", modules["A"].text)

    def test_text_outside_a_module_fails(self):
        for outside in [
            "`define W 4\n",
            "`timescale 1ns/1ps\n",
            "package p; endpackage\n",
        ]:
            with self.subTest(outside=outside):
                with self.assertRaisesRegex(SliceError, "outside any module"):
                    modules_of(outside + "module A(input a);\nendmodule\n")

    def test_define_inside_module_fails(self):
        text = "module A(input a);\n`define W 4\nendmodule\n"
        with self.assertRaisesRegex(SliceError, "`define reaches beyond"):
            modules_of(text)

    def test_non_ansi_ports_fail(self):
        text = "module A(a, y);\n  input a;\n  output y;\nendmodule\n"
        with self.assertRaisesRegex(SliceError, "non-ANSI"):
            modules_of(text)

    def test_endmodule_in_comment_is_not_the_end(self):
        text = "module A(input a);\n  // endmodule\n  wire x;\nendmodule\n"
        modules, _ = modules_of(text)
        self.assertIn("wire x;", modules["A"].text)


class SliceTest(unittest.TestCase):
    def test_kept_child_is_a_stub(self):
        text = slice_of(DESIGN, "Outer", ["Outer", "Inner"])
        self.assertIn("module Outer(", text)
        self.assertIn("module Leaf(", text)
        self.assertIn("module Inner(", text)
        self.assertNotIn("Leaf leaf", text.split("module Outer(")[0])
        self.assertNotIn("always", text)

    def test_unkept_subtree_is_whole(self):
        text = slice_of(DESIGN, "Inner", ["Outer", "Inner"])
        self.assertEqual(text.count("module "), 2)
        self.assertIn("always @(posedge clock)", text)
        self.assertNotIn("module Outer", text)
        self.assertNotIn("module Top", text)

    def test_edit_elsewhere_leaves_slice_byte_identical(self):
        edited = DESIGN.replace("r <= _leaf_y;", "r <= _leaf_y + 4'd1;")
        before = slice_of(DESIGN, "Outer", ["Outer", "Inner"])
        after = slice_of(edited, "Outer", ["Outer", "Inner"])
        self.assertEqual(before, after)
        self.assertNotEqual(
            slice_of(DESIGN, "Inner", ["Outer", "Inner"]),
            slice_of(edited, "Inner", ["Outer", "Inner"]),
        )

    def test_port_edit_of_kept_child_changes_parent(self):
        edited = DESIGN.replace(
            "module Inner(\n  input        clock,",
            "module Inner(\n  input        clock,\n  input        reset,",
        )
        self.assertNotEqual(
            slice_of(DESIGN, "Outer", ["Outer", "Inner"]),
            slice_of(edited, "Outer", ["Outer", "Inner"]),
        )


class ElaboratedNamesTest(unittest.TestCase):
    def test_first_instance_depth_first(self):
        modules, _ = modules_of(DESIGN)
        self.assertEqual(
            elaborated_names(modules, "Top"),
            {
                "Top": "Top",
                "Outer": "Outer$Top.outer",
                "Inner": "Inner$Top.outer.inner",
                # Inner's leaf comes before Outer's own, depth first.
                "Leaf": "Leaf$Top.outer.inner.leaf",
            },
        )

    def test_instances_skip_wires_named_like_modules(self):
        text = "module Leaf(input a);\nendmodule\nmodule T(input a);\n  wire Leaf;\n  Leaf l (.a(a));\nendmodule\n"
        modules, _ = modules_of(text)
        self.assertEqual(modules["T"].instances(set(modules)), [("Leaf", "l")])

    def test_instance_with_parameters(self):
        text = "module P #(parameter W = 1) (input a);\nendmodule\nmodule T(input a);\n  P #(.W(2)) p (.a(a));\nendmodule\n"
        modules, _ = modules_of(text)
        self.assertEqual(modules["T"].instances(set(modules)), [("P", "p")])

    def test_slice_names_its_module_and_stubs(self):
        modules, order = modules_of(DESIGN)
        text = slice_text(
            modules,
            order,
            "Outer",
            {"Outer", "Inner"},
            elaborated_names(modules, "Top"),
        )
        self.assertTrue(
            text.startswith(
                "// verilog_slice: Outer Outer$Top.outer\n"
                "// verilog_slice: Inner Inner$Top.outer.inner\n"
            )
        )


class MainTest(unittest.TestCase):
    def run_main(self, files, argv):
        written = {}

        def fake_open(path, mode="r"):
            if "w" in mode:
                buf = io.StringIO()
                buf.close = lambda: written.__setitem__(path, buf.getvalue())
                return buf
            return io.StringIO(files[path])

        stderr = io.StringIO()
        with mock.patch("builtins.open", fake_open), mock.patch(
            "os.path.isdir", return_value=False
        ), mock.patch("sys.stderr", stderr):
            rc = verilog_slice.main(argv)
        return rc, written, stderr.getvalue()

    def test_writes_one_slice_per_module(self):
        rc, written, _ = self.run_main(
            {"d.sv": DESIGN},
            [
                "--top",
                "Top",
                "--slice",
                "Outer",
                "o.v",
                "--slice",
                "Inner",
                "i.v",
                "d.sv",
            ],
        )
        self.assertEqual(rc, 0)
        self.assertEqual(sorted(written), ["i.v", "o.v"])

    def test_missing_kept_module_fails(self):
        rc, written, err = self.run_main(
            {"d.sv": DESIGN}, ["--top", "Top", "--slice", "Nope", "n.v", "d.sv"]
        )
        self.assertEqual(rc, 1)
        self.assertEqual(written, {})
        self.assertIn("Nope", err)

    def test_parameterized_kept_module_fails(self):
        text = DESIGN.replace("module Inner(", "module Inner #(parameter W = 4) (")
        rc, _, err = self.run_main(
            {"d.sv": text}, ["--top", "Top", "--slice", "Inner", "i.v", "d.sv"]
        )
        self.assertEqual(rc, 1)
        self.assertIn("has parameters", err)

    def test_kept_module_outside_top_fails(self):
        rc, _, err = self.run_main(
            {"d.sv": DESIGN}, ["--top", "Inner", "--slice", "Outer", "o.v", "d.sv"]
        )
        self.assertEqual(rc, 1)
        self.assertIn("not under Inner", err)

    def test_duplicate_definition_fails(self):
        rc, _, err = self.run_main(
            {"a.sv": DESIGN, "b.sv": DESIGN},
            ["--top", "Top", "--slice", "Inner", "i.v", "a.sv", "b.sv"],
        )
        self.assertEqual(rc, 1)
        self.assertIn("defined twice", err)


if __name__ == "__main__":
    unittest.main()
